const search=ref(''),importInput=ref<HTMLInputElement|null>(null)
const sessions=ref<LearningSession[]>([]),selectedUid=ref(''),input=ref(''),draft=ref(''),sources=ref<string[]>([]),draftSources=ref<string[]>([]),title=ref('学习笔记'),reference=ref(false),confirmed=ref(false),busy=ref(false),error=ref(''),notice=ref(''),before=ref('')
interface SavePayload {revision:number;operationUid:string;title:string;content:string;sources:string[];targetUid?:string;targetVersion?:number;baseContent?:string;folderUid?:string|null;areaUid?:string|null;projectUid?:string|null;folderId?:number|null;tagUids?:string[];tagIds?:number[]}
