function install(s:LearningSession){loading=true;const i=sessions.value.findIndex(x=>x.uid===s.uid);if(i<0)sessions.value.unshift(s);else sessions.value[i]=s;selectedUid.value=s.uid;input.value=s.input;draft.value=s.draft;draftSources.value=[...s.draftSources];sources.value=sources.value.filter(id=>s.messages.some(m=>m.uid===id));loading=false;persist()}
