async function initialize(){loading=true;try{key=learningScope();const cached=readLearningCache(localStorage,key);epoch=cached.epoch;sessions.value=cached.sessions;selectedUid.value=cached.selectedUid;input.value=cached.input;draft.value=cached.draft;sources.value=cached.sources||[];draftSources.value=session.value?.draftSources||[];selectedReferences.value=cached.references||[];sendOperation=cached.pendingSend;pendingSave.value=cached.operation?JSON.parse(cached.operation.payload):null;reference.value=false;confirmed.value=false}catch(e){error.value=e instanceof Error?e.message:'缓存加载失败'}finally{loading=false}if(!key)return;await run(async()=>{const remote=await learningService.list();assertScope();for(const s of remote){const index=sessions.value.findIndex(x=>x.uid===s.uid);if(index<0)sessions.value.push(s);else if(s.revision>sessions.value[index].revision){const cached=sessions.value[index];sessions.value[index]={...s,input:cached.input,draft:cached.draft}}}notice.value='会话已加载；本机未提交输入和草稿保留。重载可获取其他设备最新内容。';try{const provider=await learningService.provider();assertScope();providerText.value=provider.available?`${provider.provider} / ${provider.model}（${provider.source==='personal'?'个人配置':provider.source==='client'?'客户端直连':provider.source==='account'?'服务端调用':'管理员默认'}）`:clientMode.value?'请在“模型与调用通道”中填写本地或个人云端模型':'AI 尚未配置，请在设置中配置账号服务'}catch{providerText.value='模型服务信息未载入；请确认个人AI设置'}})
if(error.value&&!clientMode.value){error.value='账号讨论暂时无法加载。当前服务器可能尚未更新 AI 学习接口，或服务暂时不可用。本机输入与缓存已保留；可在上方选择个人云端模型或本地模型继续使用。';providerText.value='账号服务未就绪，请配置直连模型或更新服务端'}
}
async function newSession(seed=''){persist();await run(async()=>{title.value=seed.trim().replace(/\s+/g,' ').slice(0,40)||'新讨论';const s=await learningService.create(title.value);assertScope();if(!seed)selectedReferences.value=[];confirmed.value=false;sources.value=[];pendingSave.value=null;install(s);useSelection()})}
async function reload(){if(!window.confirm(clientMode.value?'重新加载本机讨论？当前输入会先保留恢复副本。':'将先保留本机恢复副本，再重载云端内容。继续？'))return;await run(async()=>{localStorage.setItem(key+':recovery',JSON.stringify(snapshot()));const remote=await learningService.list();assertScope();sessions.value=remote;if(selectedUid.value){const s=remote.find(x=>x.uid===selectedUid.value);if(s)install(s);else{selectedUid.value='';input.value='';draft.value=''}}pendingSave.value=null;notice.value=clientMode.value?'已重新加载本机讨论':'已重载云端；原本机内容保留为恢复副本。'})}
async function syncDraft(){await run(async()=>{const s=session.value;if(!s)return;const saved=await learningService.edit(s.uid,{revision:s.revision,input:input.value,draft:draft.value,sources:draftSources.value.length?draftSources.value:undefined});assertScope();install(saved);notice.value=clientMode.value?'输入与草稿已保存到本机':'输入与草稿已保存到云端'})}
let sendOperation:{signature:string;uid:string}|undefined
const inputComposing=ref(false)
function questionKeydown(event:KeyboardEvent){
 if(event.key!=='Enter'||event.isComposing||inputComposing.value||event.keyCode===229||event.shiftKey||event.altKey)return
 event.preventDefault()
 void send()
}
async function send(){querySettingsOpen.value=false;if(!busy.value)modelStatus.value=null;queryStatus.value='';if(busy.value||!input.value.trim())return;if(workspaceEnabled.value&&(!queryScope.value.enabled||!queryScope.value.kinds.includes('note'))){error.value='请在本机资料中开启笔记范围';return}if(!session.value){const question=input.value;await newSession(question);if(!session.value)return;input.value=question;await nextTick();confirmed.value=true}if(!hasConsent('send')){askConsent('send');return}confirmed.value=true;authorizedAction.value='send';oneTimeConsent='';if(reference.value&&props.note?.aiPolicy==='excluded'){error.value='该笔记已排除 AI';return}const s=session.value;if(!s||!confirmed.value)return;const signature=JSON.stringify([s.uid,input.value,assistant.value,selectedReferences.value,queryScope.value,reference.value?props.note:null]);if(sendOperation?.signature!==signature)sendOperation={signature,uid:crypto.randomUUID()};const op=sendOperation;persist();await run(async()=>{requestAbort=new AbortController();canCancel.value=true;let saved:LearningSession;try{saved=await learningService.send(s.uid,{revision:s.revision,text:input.value,instruction:activeAssistant.value.prompt,references:selectedReferences.value,queryScope:queryScope.value,workspace:workspaceEnabled.value,onModelStatus:(status:ModelStatus)=>{assertScope();modelStatus.value=status},onQueryStatus:(status:string)=>{assertScope();queryStatus.value=status},referenceUid:reference.value?props.note?.uid:undefined,confirmed:true,operationUid:op.uid,referenceVersion:reference.value?props.note?.version:undefined,referenceContent:reference.value?props.note?.content||'':undefined},requestAbort.signal,progress=>{assertScope();sessions.value=sessions.value.map(item=>item.uid===progress.uid?progress:item);input.value=progress.input})}catch(error){if(clientMode.value){sendOperation=undefined;try{install(await learningService.get(s.uid))}catch{/* retain existing input */}}throw error}assertScope();install(saved);sendOperation=undefined;notice.value=saved.messages.some(m=>m.status==='pending')?'请求仍未完成，请稍后重载或标记中断。':'讨论已保存'})}
function excerpt(){try{if(!session.value)return;draft.value=learningExcerpt(session.value,sources.value);draftSources.value=[...sources.value];pendingSave.value=null;persist()}catch(e){error.value=e instanceof Error?e.message:'摘录失败'}}
async function organize(){const s=session.value;if(!s||busy.value)return;if(!hasConsent('organize')){askConsent('organize');return}confirmed.value=true;authorizedAction.value='organize';oneTimeConsent='';await run(async()=>{requestAbort=new AbortController();canCancel.value=true;const saved=await learningService.organize(s.uid,{revision:s.revision,sources:sources.value,confirmed:true},requestAbort.signal);assertScope();install(saved);void openNoteDialog()})}
async function recover(){const s=session.value;if(!s)return;await run(async()=>{const saved=await learningService.recover(s.uid,s.revision);assertScope();install(saved);notice.value='未完成回答已标记中断；原问题保留，可主动重新发送。'})}
const noteDialog=ref<HTMLDialogElement>(),noteDialogOpen=ref(false),saveMode=ref<'create'|'append'>('create'),appendUid=ref(''),savedNoteUid=ref('')
const noteFolders=ref<FolderEntity[]>([]),noteTags=ref<TagEntity[]>([]),noteAreas=ref<AreaEntity[]>([]),appendNotes=ref<NoteEntity[]>([]),placementWarning=ref('')
const saveFolder=ref(''),saveArea=ref(''),saveTags=ref<string[]>([])
const noteOwner=()=>String(JSON.parse(readAccountSetting('note-flow-pc-user')||'null')?.userId||'local')
async function openNoteDialog(){
 stage.value='discussion';noteDialogOpen.value=true;await nextTick();noteDialog.value?.showModal();placementWarning.value=''
 const scope=learningScope();const values=await Promise.allSettled([localAiFolders(),localAiTags(),localAiWorkspace(),createPcNotesService(noteOwner()).list('active')]);if(scope!==learningScope()||!noteDialogOpen.value)return
 noteFolders.value=values[0].status==='fulfilled'?values[0].value.filter(v=>!(v as {deleted?:boolean}).deleted):[];noteTags.value=values[1].status==='fulfilled'?values[1].value.filter(v=>!(v as {deleted?:boolean}).deleted):[];noteAreas.value=values[2].status==='fulfilled'?values[2].value.areas.filter(v=>!v.archived):[];appendNotes.value=values[3].status==='fulfilled'?values[3].value.filter(v=>!v.deleted&&(!v.type||v.type==='note')&&v.contentFormat!=='file'):[]
 if(props.note)appendUid.value=props.note.uid
 if(!isCommunityEdition&&navigator.onLine!==false){const remote=await Promise.allSettled([foldersService.list(),tagsService.list()]);if(scope!==learningScope()||!noteDialogOpen.value)return;if(remote[0].status==='fulfilled')noteFolders.value=remote[0].value.filter(v=>!(v as {deleted?:boolean}).deleted);if(remote[1].status==='fulfilled')noteTags.value=remote[1].value.filter(v=>!(v as {deleted?:boolean}).deleted);if(remote.some(v=>v.status==='rejected'))placementWarning.value='部分分类未能刷新，显示本机已有选项；可留空保存。'}
}
function closeNoteDialog(){if(busy.value)return;noteDialog.value?.close();noteDialogOpen.value=false;stage.value='discussion';persist()}
async function saveNote(){
 if(!session.value||busy.value)return
 if(!pendingSave.value){try{assertScope();const sessionUid=session.value.uid;const target=saveMode.value==='append'?await createPcNotesService(noteOwner()).get(appendUid.value):undefined;assertScope();if(session.value?.uid!==sessionUid)throw Error('讨论已切换，请重新打开保存弹窗');if(saveMode.value==='append'&&(!target||target.deleted))throw Error('请选择仍可用的目标笔记');const folder=noteFolders.value.find(v=>v.uid===saveFolder.value);if(saveFolder.value&&!folder)throw Error('所选目录已不可用');pendingSave.value={revision:session.value.revision,operationUid:crypto.randomUUID(),title:title.value,content:draft.value,sources:[...draftSources.value],...(target?{targetUid:target.uid,targetVersion:target.version,baseContent:target.content}:{folderUid:folder?.uid||null,folderId:folder?.id||null,areaUid:folder?(folder.areaUid||null):(saveArea.value||null),projectUid:folder?.projectUid||null,tagUids:[...saveTags.value],tagIds:noteTags.value.filter(v=>saveTags.value.includes(v.uid)).map(v=>v.id)})};persist()}catch(source){error.value=source instanceof Error?source.message:'无法准备保存';return}}
 await commit()
}
async function commit(){const s=session.value,payload=pendingSave.value;if(!s||!payload)return;await run(async()=>{const saved=await learningService.save(s.uid,payload);assertScope();notice.value=`学习成果已保存${saved.replayed?'（已恢复上次保存结果）':''}`;pendingSave.value=null;savedNoteUid.value=saved.noteUid;noteDialog.value?.close();noteDialogOpen.value=false;stage.value='discussion';emit('saved',saved.noteUid)})}
async function exportBackup(){await run(async()=>{persist();let cloud:unknown=null;try{cloud=await learningService.archive();assertScope()}catch{notice.value='云端不可用；本次仅备份本机缓存。'}const backup={schemaVersion:1,scope:key,cache:snapshot(),cloud};const blob=new Blob([JSON.stringify(backup,null,2)],{type:'application/json'});if(!await saveLocalExport(blob,'ai-learning-backup.json',{},assertScope))return;notice.value+=' 学习备份已导出（含输入、草稿和已缓存来源，不含AI服务密钥）。'},false)}
function restoreCache(value:LearningCache){const cached=validateLearningCache(value);if(cached.epoch!==epoch)throw new Error('备份属于旧数据代次，不能自动恢复已重置的数据');loading=true;epoch=cached.epoch;sessions.value=cached.sessions;selectedUid.value=cached.selectedUid;input.value=cached.input;draft.value=cached.draft;sources.value=cached.sources||[];draftSources.value=session.value?.draftSources||[];selectedReferences.value=cached.references||[];pendingSave.value=cached.operation?JSON.parse(cached.operation.payload):null;sendOperation=cached.pendingSend;loading=false;persist()}
async function importBackup(event:Event){const element=event.target as HTMLInputElement,file=element.files?.[0];element.value='';if(!file)return;await run(async()=>{if(file.size>20000000)throw new Error('学习备份不能超过20MB');const backup=JSON.parse(await file.text());if(backup.schemaVersion!==1||backup.scope!==key||!Array.isArray(backup.cache?.sessions))throw new Error('学习备份账号或服务不匹配');if(!window.confirm(clientMode.value?'恢复当前空间学习备份？已有本机讨论不会被覆盖。':'恢复该账号学习备份到本机，并将缺失会话恢复到云端？云端已有会话不会被覆盖。'))return;localStorage.setItem(key+':recovery',JSON.stringify(snapshot()));restoreCache(validateLearningCache(backup.cache));try{const cloud=backup.cloud||{schemaVersion:1,accountId:Number(decodeURIComponent(key.split(':').at(-1)||'')),syncEpoch:epoch,sessions:backup.cache.sessions,results:[]};await verifyEpoch();const result=await learningService.restore(cloud);assertScope();notice.value=`${clientMode.value?'本机':'云端'}新增 ${result.restored} 个会话、保留 ${result.skipped} 个已有会话。`}catch(e){notice.value='本机已恢复，云端恢复尚未完成；请联网后重新导入。';throw e}},false)}
function recoverLocal(){try{assertScope();const raw=localStorage.getItem(key+':recovery');if(!raw)throw new Error('暂无本机恢复副本');const cached=JSON.parse(raw);restoreCache(validateLearningCache(cached));notice.value='已恢复本机副本；云端内容未更改，保存时仍需版本校验。'}catch(e){error.value=e instanceof Error?e.message:'恢复失败'}}
async function deleteSession(){const s=session.value;if(!s||!window.confirm('删除当前讨论？已保存笔记及来源快照会保留。'))return;await run(async()=>{await learningService.remove(s.uid,s.revision);assertScope();sessions.value=sessions.value.filter(x=>x.uid!==s.uid);selectedUid.value='';input.value='';draft.value='';sources.value=[];draftSources.value=[];pendingSave.value=null})}
function collapsePanels(){if(window.innerWidth<1360)assistantVisible.value=false;if(window.innerWidth<1000)historyVisible.value=false}
window.addEventListener('resize',collapsePanels)
window.addEventListener('resize',positionModelMenu)
window.addEventListener('scroll',positionModelMenu,true)
document.addEventListener('pointerdown',modelOutside)
document.addEventListener('pointerdown',closeTools)
document.addEventListener('keydown',closeTools)
document.addEventListener('keydown',modelEscape)
window.addEventListener('note-flow:account-data-reset',accountReset)
watch(()=>permissionScope(),()=>{rememberedConsent='';oneTimeConsent='';confirmed.value=false},{flush:'sync'})
watch(queryScope,()=>{confirmed.value=false;if(!queryScope.value.enabled||!queryScope.value.kinds.includes('note'))workspaceEnabled.value=false},{deep:true})
watch(workspaceEnabled,()=>{confirmed.value=false})
watch(reference,()=>{confirmed.value=false})
watch(selectedReferences,()=>{confirmed.value=false;persist()},{deep:true})
watch(sources,()=>{if(authorizedAction.value==='organize')confirmed.value=false},{deep:true})
watch(()=>session.value?.messages.at(-1)?.content,async()=>{await nextTick();if(followLatest.value)messageHost.value?.scrollTo({top:messageHost.value.scrollHeight})})
function trackScroll(){const host=messageHost.value;if(host)followLatest.value=host.scrollHeight-host.scrollTop-host.clientHeight<100}
function jumpLatest(){followLatest.value=true;messageHost.value?.scrollTo({top:messageHost.value.scrollHeight,behavior:'smooth'})}
watch([input,draft,sources,draftSources,pendingSave],persist,{deep:true,flush:'sync'})
watch(()=>props.selectedText,text=>{if(props.open&&text?.trim()){queuedSelection=text;useSelection()}})
watch(()=>selectedUid.value,()=>{consolidation.value=null;noteSeries.value=undefined;if(noteDialogOpen.value)closeNoteDialog()},{flush:'sync'})
watch(()=>props.note,()=>{reference.value=false;confirmed.value=false;pendingSave.value=null})
watch(()=>props.open,async open=>{if(!open){consolidation.value=null;folderOrganizationOpen.value=false;noteSeries.value=undefined;querySettingsOpen.value=false;closeTools()}clearInterval(scopeTimer);if(open){await initialize();if(props.selectedText?.trim()){queuedSelection=props.selectedText;useSelection()}scopeTimer=setInterval(()=>{try{assertScope()}catch{sessions.value=[];selectedUid.value='';input.value='';draft.value='';selectedReferences.value=[];consolidation.value=null;folderOrganizationOpen.value=false;noteSeries.value=undefined;querySettingsOpen.value=false;closeTools();key='';emit('close')}},500)}else persist()},{immediate:true})
onBeforeUnmount(()=>{noteDialog.value?.close();window.removeEventListener('note-flow:ai-transport-status',transportStatus);window.removeEventListener('resize',positionModelMenu);window.removeEventListener('scroll',positionModelMenu,true);document.removeEventListener('pointerdown',modelOutside);document.removeEventListener('pointerdown',closeTools);document.removeEventListener('keydown',closeTools);document.removeEventListener('keydown',modelEscape);window.removeEventListener('resize',collapsePanels);window.removeEventListener('note-flow:account-data-reset',accountReset);requestAbort?.abort();clearInterval(scopeTimer);persist()})
