<template>
<ElDialog v-if="open" v-model="querySettingsOpen" append-to-body title="本机资料查询范围" width="min(480px,94vw)" :close-on-click-modal="!busy" :close-on-press-escape="!busy">
 <div class="query-settings"><label class="learning-checkbox"><input v-model="queryScope.enabled" type="checkbox" :disabled="busy"/>允许助手查询本机资料</label><template v-if="queryScope.enabled"><label>领域范围<ElSelect v-model="queryScope.areaUid" aria-label="本机资料领域范围" :disabled="busy"><ElOption label="当前空间的所有领域" value=""/><ElOption v-for="area in queryAreas" :key="area.uid" :label="queryAreaLabel(area)" :value="area.uid"/></ElSelect></label><div class="query-kinds"><label v-for="kind in [['note','笔记'],['knowledge','知识'],['task','任务']].filter(item=>knowledgeAvailable||item[0]!=='knowledge')" :key="kind[0]" class="learning-checkbox"><input v-model="queryScope.kinds" type="checkbox" :value="kind[0]" :disabled="busy"/>{{kind[1]}}</label></div><label class="learning-checkbox"><input v-model="queryScope.includeCompletedTasks" type="checkbox" :disabled="busy"/>包含已完成任务</label><label v-if="!isCommunityEdition&&queryScope.kinds.includes('note')" class="learning-checkbox"><input v-model="workspaceEnabled" type="checkbox" :disabled="busy"/>笔记工作区：允许连续读取并准备目录和正文变更，确认后应用</label><p v-if="workspaceEnabled">助手可在选定领域连续搜索、读取完整笔记，准备新增、编辑、重命名和移动方案；查询内容按需发送给当前模型。所有修改先进入会话方案，确认一次才写入。</p><p v-else>讨论目录分类时，读取本范围的目录层级、可分析笔记标题和分布，不读取正文；超出上下文长度会明确标注覆盖范围。</p><p v-if="!workspaceEnabled">普通资料问答最多搜索 10 项、读取 5 项正文。排除 AI、归档及回收站内容不参与笔记查询；查询只读，不修改资料。</p></template></div><template #footer><ElButton type="primary" @click="querySettingsOpen=false">完成</ElButton></template>
</ElDialog>
<AiNoteSeriesDialog v-if="!isCommunityEdition&&open&&noteSeries" :owner-id="noteOwner()" :session="noteSeries.session" :through-uid="noteSeries.throughUid" @close="noteSeries=undefined" @created="seriesCreated"/>
<FolderOrganizationDialog v-if="open&&folderOrganizationOpen" :owner-id="noteOwner()" @close="folderOrganizationOpen=false" @changed="notice='笔记目录已更新'"/>
<Teleport to="body"><NoteConsolidationDialog v-if="open&&consolidation" :notes="consolidation.notes" :folders="consolidation.folders" :owner-id="consolidation.ownerId" :initial-instruction="consolidation.instruction" @close="consolidation=null" @changed="consolidationChanged"/></Teleport>
<aside v-if="open" class="learning-sidebar" :class="{embedded}">
<section class="learning-panel" aria-label="AI学习讨论" :class="{'history-visible':historyVisible,'history-collapsed':historyCollapsed,'assistant-hidden':!assistantVisible}">
 <aside class="learning-history"><div class="history-top"><button class="history-new" :disabled="busy" @click="newSession();stage='discussion';historyVisible=false"><Plus/> 新对话</button><button class="learning-icon-button" aria-label="收起对话列表" @click="historyCollapsed=true;historyVisible=false"><Close/></button></div><input v-model="search" placeholder="搜索对话…" aria-label="搜索讨论"/><nav aria-label="历史讨论"><section v-for="group in historyGroups" :key="group.label" class="history-group"><h3 v-if="group.label!=='已保存的讨论'">{{group.label}}</h3><button v-for="item in group.items" :key="item.uid" :class="{active:item.uid===selectedUid}" :disabled="busy" @click="choose(item.uid);stage='discussion'"><span>{{item.title||'新讨论'}}</span><time>{{historyDate(item)}}</time></button></section><p v-if="!filteredSessions.length">{{search?'没有匹配的讨论':'开始对话，留下新的想法'}}</p></nav><small>讨论保存在当前本地空间</small></aside>
 <div ref="mainArea" class="learning-main">
  <header class="learning-header"><div class="learning-title"><button class="learning-text-button history-toggle" aria-label="历史讨论" @click="historyCollapsed=false;historyVisible=!historyVisible"><ChatDotRound/></button><div><h2>{{session?.title||(note?'笔记讨论':'AI 学习讨论')}}</h2><time v-if="session?.createdAt">{{new Date(session.createdAt).toLocaleString('zh-CN',{hour12:false})}}</time><small v-else>让想法在对话中生长</small></div></div><div class="learning-header-actions"><button class="learning-icon-button" aria-label="复制当前讨论" :disabled="!session?.messages.length" @click="copyMessage(session!.messages.map(m=>m.content).join('\n\n'))"><CopyDocument/></button><button class="learning-icon-button" aria-label="重命名讨论" :disabled="busy||!session" @click="renameSession"><Edit/></button><button class="learning-icon-button" aria-label="删除当前讨论" :disabled="busy||!session" @click="deleteSession"><Delete/></button><button v-if="!embedded" class="learning-icon-button" aria-label="关闭学习讨论" @click="emit('close')"><Close/></button></div></header>
  <p v-if="note" class="learning-note-context">讨论笔记：{{note.title||'未命名笔记'}}<small>仅在勾选引用后发送正文</small></p>
  <section v-if="modelSettingsVisible" ref="modelMenu" :style="modelMenuStyle" class="learning-model-popover" aria-label="选择模型"><h3>选择模型</h3><button v-for="option in modelOptions" :key="option.channel" class="model-option" :aria-pressed="aiClientConfig().channel===option.channel" @click="switchModel(option)"><span>{{optionLabel(option)}}<small>{{option.channel==='local'?'本地模型':option.channel==='personal'?'个人直连':'账号服务'}}</small></span><Checked v-if="aiClientConfig().channel===option.channel"/></button><p v-if="!modelOptions.length">尚未配置可用模型，讨论和草稿仍可保存在本机。</p><button class="manage-models" @click="manageModels"><Setting/>管理模型…</button></section>
  <details ref="toolsMenu" class="learning-tools" @click="event=>{if((event.target as HTMLElement).closest('button'))closeTools()}"><summary><span>记录与工具</span><span>更多操作 <i>⌄</i></span></summary><div class="learning-tools-body"><div class="learning-actions"><button v-if="!isCommunityEdition" :disabled="busy||!session?.messages.some(m=>m.status==='complete'&&m.role==='assistant')" @click="openNoteSeries()">生成系列笔记</button><button :disabled="busy" @click="folderOrganizationOpen=true">整理笔记目录</button><button v-if="!isCommunityEdition" :disabled="busy||consolidationPreparing" @click="openConsolidation(true)">整合记录</button><button v-if="!isCommunityEdition" :disabled="busy" @click="importOldDiscussions">导入旧版账号讨论</button><button :disabled="busy" @click="reload">{{clientMode?'重新加载本机':'从云端重载'}}</button><button v-if="session" :disabled="busy" @click="syncDraft">{{clientMode?'保存输入和草稿':'保存输入和草稿到云端'}}</button><button :disabled="busy" @click="exportBackup">导出学习备份</button><button :disabled="busy" @click="importInput?.click()">恢复学习备份</button><button :disabled="busy" @click="recoverLocal">恢复重载前本机草稿</button><button v-if="session" :disabled="busy" @click="renameSession">重命名讨论</button><button v-if="session" class="learning-danger" :disabled="busy" @click="deleteSession">删除当前会话</button></div></div></details>
  <input ref="importInput" type="file" accept="application/json,.json" hidden @change="importBackup"/>
  <p v-if="error" role="alert" class="learning-feedback">{{error}}</p><p v-if="notice&&!notice.startsWith('会话已加载')&&notice!=='讨论已保存'" role="status" class="learning-feedback" :title="notice">{{notice}}</p>
  <a v-if="savedNoteUid" class="learning-hint" :href="router.resolve(`/notes?note=${savedNoteUid}`).href">打开已保存笔记</a><nav v-if="session" class="learning-tabs" aria-label="学习工作区"><button :class="{active:stage==='discussion'}" :aria-pressed="stage==='discussion'" @click="stage='discussion'">讨论</button><button :class="{active:stage==='draft'}" :aria-pressed="stage==='draft'" v-if="draft.trim()||draftSources.length" @click="openNoteDialog">笔记草稿 <span v-if="draft.trim()" class="learning-dot"/></button></nav>
  <div v-if="!session" class="learning-empty"><span class="learning-empty-mark">✦</span><h3>从一个好问题开始</h3><p>边讨论，边留下值得记住的想法。<br/>在下方输入问题，开始你的学习主题。</p><div class="learning-starters"><button @click="starter('请用通俗语言和具体例子解释：')">解释一个概念</button><button @click="starter('帮我围绕这个主题制定学习计划：')">制定学习计划</button><button @click="starter('帮我梳理下面内容的关键观点：')">梳理学习要点</button></div><small>讨论保存在本机，发送范围由你选择。</small></div>
  <template v-if="session">
    <div v-show="stage==='discussion'" class="learning-discussion">
      <div v-if="!session.messages.length" class="learning-conversation-empty"><span>✦</span><h3>今天想弄懂什么？</h3><p>问一个问题，或引用当前笔记一起讨论。</p></div>
      <div ref="messageHost" @scroll="trackScroll" class="learning-messages"><article v-for="message in session.messages" :key="message.uid" :class="{'learning-user-message':message.role==='user'}"><div class="message-avatar" aria-hidden="true">{{message.role==='user'?'我':'✦'}}</div><div class="message-body"><div class="learning-message-meta"><span>{{message.role==='user'?'我的问题':'AI 回答'}}</span><label v-if="selectingSources&&message.status==='complete'" class="learning-source-choice"><input v-model="sources" type="checkbox" :value="message.uid" :disabled="busy"/><span>{{sources.includes(message.uid)?'已选为来源':'选为来源'}}</span></label><span v-else-if="message.status!=='complete'" class="learning-message-state">{{message.status==='pending'?'未完成':message.status==='interrupted'?'已中断':'失败'}}</span></div><div class="message-content"><LearningMessageContent v-if="message.role==='assistant'&&message.content" :streaming="message.status==='pending'" :content="!isCommunityEdition&&message.status==='complete'?parseLearningSkill(message.content).text:message.content"/><pre v-else>{{message.content||(message.status==='pending'?(modelStatus?phaseLabel:'正在等待模型回答…'):message.status==='interrupted'?'生成已停止，问题已保留，可重新提问。':'模型未返回回答，请查看下方错误提示或重新提问。')}}</pre></div><LearningSkillCard v-if="!isCommunityEdition&&message.role==='assistant'&&message.status==='complete'&&(parseLearningSkill(message.content).call||parseLearningSkill(message.content).error)" :key="key+message.uid" :session="session" :message-uid="message.uid" :owner-id="noteOwner()" :disabled="busy" @saved="uid=>{savedNoteUid=uid;emit('saved',uid)}"/><details v-if="message.directorySnapshot" class="learning-directory-evidence"><summary>已读取目录 {{message.directorySnapshot.includedFolders}}/{{message.directorySnapshot.folderCount}} · 笔记标题 {{message.directorySnapshot.includedTitles}}/{{message.directorySnapshot.noteCount}} · {{message.directorySnapshot.complete?'完整范围':'部分范围'}}</summary><p>{{message.directorySnapshot.areaLabel}} · {{new Date(message.directorySnapshot.capturedAt).toLocaleString()}} · 不含正文</p><pre>{{message.directorySnapshot.content}}</pre></details><details v-if="message.references?.length" class="learning-hint"><summary>引用来源 · {{message.references.length}} 项</summary><section v-for="item in message.references" :key="item.kind+item.uid"><a v-if="item.kind!=='attachment'" :href="router.resolve(item.kind==='note'?`/notes?note=${item.uid}`:item.kind==='knowledge'?`/knowledge/${item.uid}`:`/tasks?task=${item.uid}`).href">{{item.title}}</a><b v-else>{{item.title}}</b><small v-if="item.truncated">（已截取 {{item.content.length}} / {{item.fullLength}} 字）</small><details><summary>查看引用快照</summary><pre>{{item.content}}</pre></details></section></details><div v-if="message.status==='complete'" class="learning-message-actions"><button @click="copyMessage(message.content)"><CopyDocument/>复制</button><button v-if="message.role==='assistant'" :disabled="busy" @click="saveMessage(message.uid)"><Notebook/>保存为笔记</button><button v-if="!isCommunityEdition&&message.role==='assistant'" :disabled="busy" @click="openNoteSeries(message.uid)"><Folder/>生成系列笔记</button><button v-if="knowledgeAvailable&&message.role==='assistant'" :disabled="busy" @click="actionDialog?.open('knowledge',session,message)">沉淀为知识</button><button v-if="message.role==='assistant'" :disabled="busy" @click="actionDialog?.open('tasks',session,message)">规划任务</button><button :disabled="busy" @click="selectingSources=!selectingSources">{{selectingSources?'退出多选':'多选整理'}}</button></div><button v-else-if="message.status==='failed'||message.status==='interrupted'" class="learning-text-button" :disabled="busy" @click="retryQuestion"><Refresh/>重新提问</button></div></article></div>
      <div v-if="selectingSources&&sources.length" class="learning-selection"><span>已选 {{sources.length}} 条来源</span><div><button :disabled="busy" @click="excerpt();openNoteDialog()">摘录所选原文</button><button :disabled="busy" @click="organizeForDraft">AI 整理所选讨论</button></div></div>
      <LearningWorkspacePlan v-if="!isCommunityEdition&&session" :key="key+session.uid" :session-uid="session.uid" :disabled="busy" @busy-change="value=>{busy=value}" @resume="resumeWorkspace"/>
      <p v-if="modelStatus&&timingText" class="model-timing">{{timingText}}<span>（从本次模型请求开始计时）</span></p><p v-if="canCancel&&queryStatus" class="learning-hint">{{queryStatus}}</p><p v-if="canCancel" class="learning-generating" role="status"><span class="learning-pulse"/>{{phaseLabel}} 问题已保存在本机</p><button v-if="!busy&&session.messages.some(m=>m.status==='pending')" class="learning-recover" :disabled="busy" @click="recover">上次请求已中断，保留输入继续</button>

    </div>
  </template>
      <button v-if="!followLatest" class="learning-text-button" @click="jumpLatest">回到最新</button><section v-if="stage==='discussion'" class="learning-composer"><div v-if="selectedReferences.length" class="selected-references"><div v-for="item in selectedReferences" :key="item.kind+item.uid" class="reference-chip"><button :disabled="busy" @click="referencePicker?.open()"><Notebook/>{{item.title}}</button><button :aria-label="'移除引用 '+item.title" :disabled="busy" @click="selectedReferences=selectedReferences.filter(value=>value!==item)"><Close/></button></div></div><label class="learning-question-label">{{session?.messages.length?'继续追问':'你的学习问题'}}<textarea v-model="input" maxlength="8000" rows="2" placeholder="输入问题或追问；先保存在本机" @keydown="questionKeydown" @compositionstart="inputComposing=true" @compositionend="inputComposing=false" :disabled="busy"/></label><p class="learning-model">{{providerText}}</p><p v-if="selectedText" class="learning-hint">所选内容已放入问题，默认不引用整篇笔记。</p><details v-show="contextVisible" :open="contextVisible||undefined" class="learning-context"><summary><span>{{reference?'当前笔记 + 最近20条讨论':'当前问题 + 最近20条讨论'}} <i>⌄</i></span><span>{{channelLabel}}</span></summary><div><label v-if="note" class="learning-checkbox"><input v-model="reference" type="checkbox" :disabled="note.aiPolicy==='excluded'||busy"/><span>本次引用当前笔记全部正文：{{note.title||'未命名笔记'}}{{note.aiPolicy==='excluded'?'（已排除AI）':''}}</span></label><details v-if="reference&&note"><summary>查看将引用的笔记正文</summary><pre>{{note.content}}</pre></details><p class="learning-hint">仅发送你输入的讨论及明确选择的笔记，最近20条完整消息及当前问题，总上限24000字符。{{channelLabel}}。AI 回答和引用均未经核实。输入与草稿先保存在本机；重试创建新一轮。</p></div></details><div class="learning-send-row"><div class="composer-tools"><ElButton text size="small" class="composer-chip query-scope-trigger" aria-label="本机资料查询范围" :title="queryScopeSummary" :aria-pressed="queryScope.enabled" :disabled="busy" @click="openQuerySettings">{{queryScopeSummary}}<span v-if="workspaceEnabled"> · 工作区</span><span v-else-if="queryScope.enabled"> · 已开启</span></ElButton><button class="composer-chip" aria-label="添加引用" :disabled="busy" @click="referencePicker?.open()"><Plus/>添加引用</button><button v-if="!isCommunityEdition" class="composer-chip" :disabled="busy||consolidationPreparing||consolidationNoteCount<2" :title="consolidationNoteCount<2?'先添加至少两篇笔记引用':'仅整合所选笔记；输入框内容作为补充要求'" @click="openConsolidation()"><Notebook/>{{consolidationPreparing?'准备中…':'整合笔记'}}</button><button ref="modelTrigger" class="composer-chip learning-model-picker" aria-haspopup="true" :disabled="busy" :aria-expanded="modelSettingsVisible" @click="openModels">{{modelLabel}}⌄</button><select v-model="assistant" class="composer-chip assistant-chip" aria-label="选择助手" :disabled="busy"><option v-for="item in assistants" :key="item.id" :value="item.id">{{item.name}}</option></select></div><button v-if="canCancel" class="learning-text-button" @click="cancelRequest">停止生成</button><button v-else class="learning-primary" :disabled="busy||!input.trim()" @click="send"><Promotion/>{{busy?'发送中…':'发送'}}</button></div></section>
<p v-if="stage==='discussion'" class="composer-footnote">{{destinationHint}} · {{saveState}} · Enter 发送 · Shift+Enter 换行 · AI 回答请核实</p>
</div>
<Teleport to="body"><dialog ref="noteDialog" class="learning-note-dialog" aria-labelledby="learning-note-dialog-title" @cancel.prevent="closeNoteDialog"><header><h3 id="learning-note-dialog-title">保存为笔记</h3><button aria-label="关闭保存笔记" :disabled="busy" @click="closeNoteDialog">×</button></header><div class="note-dialog-body"><p v-if="error" role="alert">{{error}}</p><label>保存方式<select aria-label="保存方式" v-model="saveMode" :disabled="busy||!!pendingSave"><option value="create">新建笔记</option><option value="append">追加到已有笔记</option></select></label><label v-if="saveMode==='append'">目标笔记<select aria-label="目标笔记" v-model="appendUid" :disabled="busy||!!pendingSave"><option value="">请选择笔记</option><option v-for="item in appendNotes" :key="item.uid" :value="item.uid">{{item.title||'未命名笔记'}}</option></select></label><label v-else>笔记标题<input v-model="title" maxlength="200" :disabled="busy||!!pendingSave"/></label><label>笔记正文<textarea v-model="draft" rows="10" maxlength="50000" :disabled="busy||!!pendingSave"/></label><details v-if="saveMode==='create'" class="note-placement"><summary>归档位置与分类（可选）</summary><label>目录<FolderTreeSelect v-model="saveFolder" :folders="noteFolders" :disabled="busy||!!pendingSave"/></label><label>领域<select v-model="saveArea" :disabled="busy||!!pendingSave||!!saveFolder"><option value="">{{saveFolder?'跟随所选目录':'不指定领域'}}</option><option v-for="item in noteAreas" :key="item.uid" :value="item.uid">{{item.name}}</option></select></label><fieldset :disabled="busy||!!pendingSave"><legend>标签</legend><label v-for="item in noteTags" :key="item.uid" class="note-tag"><input v-model="saveTags" type="checkbox" :value="item.uid"/>{{item.name}}</label><small v-if="!noteTags.length">暂无已有标签，可先保存后整理。</small></fieldset><small>{{placementWarning||'选择目录后继承目录的领域与项目归属；留空也可保存。'}}</small></details><p v-else class="note-modal-hint">保留目标笔记原有目录与分类，追加前检查正文版本。</p><p class="note-modal-hint">保存 {{draftSources.length}} 条讨论来源。关闭弹窗保留本机草稿。</p></div><footer><button :disabled="busy||!!pendingSave||!draftSources.length" @click="organizeForDraft">AI 整理</button><button :disabled="busy" @click="closeNoteDialog">取消</button><button class="note-save-primary" :disabled="busy||!draft.trim()||!draftSources.length||(saveMode==='append'&&!appendUid)" @click="saveNote">{{busy?'保存中…':pendingSave?'重试保存':saveMode==='append'?'追加到笔记':'保存笔记'}}</button></footer></dialog></Teleport>
<LearningActionDialog ref="actionDialog"/><LearningReferencePicker ref="referencePicker" :selected="selectedReferences" @change="updateReferences"/>
<dialog ref="consentDialog" class="learning-send-consent" aria-labelledby="learning-consent-title" @cancel="dismissConsent"><h3 id="learning-consent-title">确认发送范围</h3><p>{{modelLabel}} · {{channelLabel}}</p><p>{{sendRangeText}}</p><p v-if="queryScope.enabled">允许查询本机{{queryScope.kinds.map(kind=>kind==='note'?'笔记':kind==='knowledge'?'知识':'任务').join('、')}}；目录结构、笔记标题、搜索摘要与选取正文按问题需要发送到当前模型。包含已完成任务：{{queryScope.includeCompletedTasks?'是':'否'}}。领域范围：{{queryScope.areaUid?queryAreas.find(v=>v.uid===queryScope.areaUid)?.name||queryScope.areaUid:'当前空间全部领域'}}。查询规划会增加模型调用次数。</p><p v-if="workspaceEnabled">本次启用笔记工作区：允许在所选领域连续读取笔记正文并准备修改方案，确认应用后才修改资料。工具处理可能产生多次模型请求。</p><p>{{consentText}}。讨论与草稿仍保存在本机。</p><details v-if="selectedReferences.length"><summary>查看引用内容</summary><section v-for="item in selectedReferences" :key="item.kind+item.uid"><b>{{item.title}}</b><pre>{{item.content}}</pre></section></details><label v-if="consentAction==='send'" class="learning-checkbox"><input v-model="rememberDiscussion" type="checkbox"/>本次讨论不再提示</label><small>切换讨论、模型或修改引用范围后重新确认；刷新页面后授权失效。</small><footer><button @click="dismissConsent">取消</button><button class="learning-primary" @click="allowAndSend">确认并发送</button></footer></dialog>
</section>
</aside>
